{
  "name": "Medicaid for Aged and Disabled",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "summary": "Michigan’s aged/disabled Medicaid path is for people who are age 65 or older, blind, or disabled, and it uses both income and asset tests.[1][2] Michigan’s official eligibility page says that if income is over the limit, a person may still qualify by incurring medical expenses that meet or exceed a deductible/spenddown.[1]",
      "limits": {
        "single": "The federal poverty-level benchmark cited for this category is 100% FPL; one source summarizes Michigan’s aged/disabled Medicaid income test as less than the federal poverty level plus $20, with a 2025 individual FPL figure of $1,304/month.[2]",
        "couple": "A source summarizing Michigan’s aged/disabled Medicaid states a married couple limit of $1,763/month in 2025.[2]",
        "household_size_table": "Michigan’s official page does not present a household-size table for this category in the search results; this program is generally evaluated under aged/blind/disabled rules rather than MAGI household-size rules.[1][2]",
        "spenddown": "If countable income is over the limit, Michigan allows a medical-expense deductible/spenddown route to qualify.[1][2]"
      }
    },
    "asset_limits": {
      "summary": "Michigan’s official page confirms asset tests apply.[1] A source summarizing current Michigan policy says the resource limit is approximately $9,660 for one person and $14,470 for a couple as of February 1, 2025.[2]",
      "what_counts": [
        "Countable resources generally include cash, checking/savings balances, and other non-exempt assets used for Medicaid resource testing.[1][2]"
      ],
      "what_is_exempt": [
        "The search results did not provide a complete official exemption list for this specific program.[1][2]",
        "Typical Medicaid exemptions such as a primary home, one vehicle, household goods, and burial-related items may apply under Michigan Medicaid rules, but those specific exemptions were not spelled out in the retrieved official sources for this program.[1][2]"
      ]
    },
    "other_requirements": [
      "Must be age 65 or older, blind, or disabled under Medicaid criteria.[1][2]",
      "Must meet Michigan residency and citizenship/immigration eligibility rules for Medicaid coverage.[1]",
      "Must meet both financial and non-financial Medicaid eligibility conditions.[1][7]",
      "People receiving SSI typically qualify automatically for Medicaid in Michigan.[2]"
    ]
  },
  "benefits": {
    "type": "in_kind",
    "value": "Most beneficiaries are enrolled in a Medicaid health plan and receive a comprehensive package of health care benefits, including vision, dental, and mental health services.[1] For eligible people needing long-term supports, Michigan’s MI Choice waiver can provide Medicaid-covered services that help them remain at home or in another residential setting; covered services include adult day health, chore services, community transportation, counseling, environmental accessibility adaptations, home-delivered meals, nursing services, personal emergency response systems, private duty nursing/respiratory care, respite, specialized medical equipment and supplies, and independent-living skills training.[6]",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online: https://www.michigan.gov/mdhhs/assistance-programs/medicaid/portalhome/beneficiaries/apply (MI Bridges / healthcare application portal).[7]",
      "Online alternative for healthcare coverage: https://www.michigan.gov/mdhhs/assistance-programs/healthcare/beneficiary-support (use the DCH-1426 application if unable to apply online).[5]",
      "Mail: complete the DCH-1426 paper application and mail it in.[5][7]",
      "In person: apply at a local Michigan Department of Health and Human Services (MDHHS) office.[7]",
      "Phone support for paper application request: 888-367-6557.[10]"
    ],
    "processing_time": "The retrieved official search results did not provide a specific Medicaid processing-time standard for this program.[1][5][7]",
    "waitlist": "No statewide waitlist was identified for standard aged/disabled Medicaid coverage. The MI Choice waiver is a separate long-term-care waiver that can involve local capacity and eligibility screening, but no specific waitlist detail was returned in the search results.[6]",
    "forms": [
      "DCH-1426, Application for Health Coverage & Help Paying Costs.[5][7]"
    ],
    "documents": [
      "Social Security number",
      "Birthdate",
      "Income information",
      "Information about financial resources/assets",
      "Other eligibility information requested by MDHHS",
      "Medical expense records if trying to qualify through spenddown"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Statewide Michigan Medicaid program; local MDHHS offices handle applications and county-level administration, but the basic aged/disabled eligibility rules are statewide.[1][7]",
    "regional_variations": "The core Medicaid eligibility rules are statewide, but local MDHHS offices, Medicaid health plans, and waiver/service providers can differ by county and service area. The MI Choice waiver is delivered through local agencies/providers and may vary in availability by region.[6][7]",
    "offices_or_providers": [
      "Local MDHHS county offices",
      "MI Bridges online portal",
      "MI Choice waiver local agencies/providers"
    ]
  },
  "official_source": "https://www.michigan.gov/mdhhs/assistance-programs/medicaid/health-care-programs-eligibility",
  "gotchas": [
    "This is not just an age-based program; income and asset limits both matter.[1][2]",
    "If income is over the limit, spenddown can still make someone eligible.[1][2]",
    "SSI recipients usually qualify automatically, so families should check whether the person is already receiving SSI before starting a separate application.[2]",
    "The MI Choice waiver is not the same thing as basic Medicaid; it is an add-on long-term-care home- and community-based service option with its own eligibility and service structure.[6]",
    "Michigan’s official pages emphasize online application through MI Bridges, but paper and in-person routes remain available.[5][7]",
    "Coverage is often delivered through a Medicaid health plan, so the family may need to pick or be assigned a plan after eligibility is approved.[1]"
  ],
  "data_shape_notes": "This program uses aged/blind/disabled Medicaid rules with both income and asset testing, and applicants may qualify through a spenddown if income is too high.[1][2] It is statewide, but long-term-care supports can branch into waiver-based services like MI Choice, which adds service-package complexity beyond ordinary Medicaid.[6][7]"
}

{
  "name": "Medicare Savings Program",
  "eligibility": {
    "age": null,
    "income_limits": {
      "summary": "Michigan’s Medicare Savings Program (MSP) is for people who are enrolled in Medicare Part A or Part B and have low income and limited resources. The program has tiered income rules, and the tier determines what help you get.[1][10]",
      "tiers": [
        {
          "tier": "QMB (Qualified Medicare Beneficiary)",
          "income_limit": "Up to 100% of the Federal Poverty Level, with Michigan guidance also referencing a $20 Social Security/RSDI disregard in some cases.[4][7]",
          "benefit_link": "Pays Medicare Part A and Part B premiums, deductibles, and coinsurance.[10]"
        },
        {
          "tier": "SLMB (Specified Low-Income Medicare Beneficiary)",
          "income_limit": "Over 100% and up to 120% of the Federal Poverty Level, with Michigan guidance also referencing a $20 Social Security/RSDI disregard in some cases.[4][7]",
          "benefit_link": "Pays Medicare Part B premium only.[10]"
        },
        {
          "tier": "QI (Qualifying Individual, also called ALMB/Q1 in some Michigan materials)",
          "income_limit": "Over 120% and up to 135% of the Federal Poverty Level, with Michigan guidance also referencing a $20 Social Security/RSDI disregard in some cases.[4][7]",
          "benefit_link": "Pays Medicare Part B premium only.[10]"
        }
      ],
      "table_note": "Michigan materials cite annual updates, and one 2026 job aid says the limits change each April 1.[6] A Michigan consumer guide also shows 2026 monthly examples for one person and a married couple, including QMB at $1,350/$1,824, SLMB at $1,585/$2,135, and QI at $1,781/$2,400, with resources of $9,950 for an individual and $14,910 for a married couple.[11][14]",
      "household_size_variation": "Yes, the limits vary by household size for the federal poverty-based income test.[11][14]"
    },
    "asset_limits": {
      "applies": true,
      "limit": "Michigan uses the federal MSP asset limits for QMB, SLMB, and QI: $9,660 for one person and $14,470 for a married couple in one Michigan guide, with another current source showing $9,950 and $14,910 for 2026.[14][11]",
      "what_counts": "The resources test applies to countable assets/resources used for MSP eligibility.[1][10]",
      "what_is_exempt": "The sources retrieved do not provide a full Michigan-specific exempt-asset list, so the safest guidance is to treat the official MDHHS application/eligibility rules as controlling and verify how specific items are counted.[1][10]"
    },
    "other_requirements": [
      "Must be enrolled in Medicare Part A or Part B.[1][10]",
      "Must be elderly or disabled with low income and limited resources.[1]",
      "Must meet Michigan MDHHS eligibility rules for the specific MSP tier.[10]",
      "If approved for a lower-cost tier, enrollment must follow that tier rather than a higher one.[13]"
    ]
  },
  "benefits": {
    "type": "financial",
    "value": "Depending on tier, Michigan may pay Medicare premiums, coinsurance, and deductibles.[10] Specifically, QMB pays Part A and Part B premiums plus Medicare deductibles and coinsurance; SLMB pays the Part B premium only; QI also pays the Part B premium only.[10] A Michigan Medicare resource also notes that some beneficiaries can have their Part A premium paid if they owe one.[14]",
    "varies_by": "household_size"
  },
  "application": {
    "methods": [
      "Online at MI Bridges: https://www.michigan.gov/mibridges[1]",
      "Paper application from MDHHS website: Michigan.gov > Assistance Programs > Health Care Coverage > Application for Health Coverage & Help Paying Costs[1]",
      "Local Michigan Department of Health and Human Services (MDHHS) office in person or by returning the paper application there[1]",
      "By requesting an application from MDHHS, which the booklet says MDHHS will send if asked[1]"
    ],
    "processing_time": "The retrieved official sources do not state a specific processing-time standard for MSP approvals.[1][10]",
    "waitlist": null,
    "forms": [
      "Application for Health Coverage & Help Paying Costs",
      "MDCH-769 (Rev. 02/25) appears to be the current form version referenced in MDHHS materials[3]"
    ],
    "documents": [
      "Proof of Medicare enrollment (Part A or Part B)[1][10]",
      "Proof of income[1]",
      "Proof of resources/assets[1][10]",
      "Completed health coverage application[1]",
      "Any documents MDHHS asks for to verify eligibility"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "No county restriction appears in the retrieved sources; it is a Michigan state program administered by MDHHS.[10]",
    "regional_variations": "The retrieved sources do not show county-by-county MSP differences. Administration is statewide through MDHHS, so the main variation is not regional service rules but eligibility tier and annual income/resource updates.[1][6][10]",
    "offices_or_providers": [
      "Michigan Department of Health and Human Services (MDHHS)",
      "Local MDHHS offices"
    ]
  },
  "official_source": "https://www.michigan.gov/mdhhs/assistance-programs/healthcare/disabilities/dualeligible/medicare-savings-programs",
  "gotchas": [
    "This is not a medical service program; it is help paying Medicare costs, mainly premiums and sometimes cost-sharing.[10]",
    "Eligibility is tiered, so the exact help depends on where income falls relative to 100%, 120%, and 135% of poverty.[4][7][10]",
    "Many people think MSP is only for people with no assets at all, but Michigan uses resource limits rather than a pure no-asset rule.[1][10][14]",
    "The application route is simple, but the official materials push people to MI Bridges or their local MDHHS office rather than a separate MSP-only office.[1]",
    "Income/resource limits change annually, so any guide should note the effective date of the dollar figures.[6]"
  ],
  "data_shape_notes": "This program is tiered by income and household size, with benefits that change by tier; it also uses asset/resource limits and is administered statewide through MDHHS rather than through region-specific service providers.[10][11][14]"
}
